package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen2Test {

    @Test(expected = IOException.class)
    public void testRead_WhenClosed_ThrowsIOException() throws IOException {
        byte[] data = createZipData("test", "content");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        zais.close();
        zais.read(new byte[10], 0, 10);
    }

    @Test
    public void testRead_WhenFinishedOrNullEntry_ReturnsMinusOne() throws IOException {
        byte[] data = createZipData("test", "content");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        // No entry selected yet, current is null
        Assert.assertEquals(-1, zais.read(new byte[10], 0, 10));

        // After reading everything, it should return -1 (simulated by reaching end of stream)
        zais.getNextZipEntry();
        zais.read(new byte[10], 0, 10); 
        // Note: In real scenarios, the next call after EOF returns -1
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_InvalidBufferBounds_ThrowsException() throws IOException {
        byte[] data = createZipData("test", "content");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        // start > buffer.length
        zais.read(new byte[5], 10, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeStart_ThrowsException() throws IOException {
        byte[] data = createZipData("test", "content");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        zais.read(new byte[5], -1, 1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_NegativeLength_ThrowsException() throws IOException {
        byte[] data = createZipData("test", "content");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        zais.read(new byte[5], 0, -1);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testRead_LengthExceedsBufferCapacity_ThrowsException() throws IOException {
        byte[] data = createZipData("test", "content");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));
        zais.getNextZipEntry();
        // buffer length 5, start 0, length 6 -> buffer.length - start (5) < length (6)
        zais.read(new byte[5], 0, 6);
    }

    @Test
    public void testRead_DeflatedContent_ReturnsData() throws IOException {
        String content = "Hello World";
        byte[] data = createZipData("test", content);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));

        zais.getNextZipEntry();
        byte[] buffer = new byte[10];
        int read = zais.read(buffer, 0, 5);

        Assert.assertEquals(5, read);
        Assert.assertEquals("Hello", new String(buffer, 0, 5));
    }

    @Test
    public void testRead_StoredContent_ReturnsData() throws IOException {
        // To test STORED method, we must create a ZIP with STORED entries
        byte[] data = createStoredZipData("stored", "storedcontent");
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));

        zais.getNextZipEntry();
        byte[] buffer = new byte[5];
        int read = zais.read(buffer, 0, 5);

        Assert.assertEquals(5, read);
        Assert.assertEquals("store", new String(buffer, 0, 5));
    }

    @Test
    public void testRead_StoredContent_MultipleReads() throws IOException {
        byte[] data = createStoredZipData("stored", "abcdefghij"); // 10 bytes
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(data));

        zais.getNextZipEntry();
        byte[] buffer = new byte[4];

        // First read
        Assert.assertEquals(4, zais.read(buffer, 0, 4));
        Assert.assertEquals("abcd", new String(buffer, 0, 4));

        // Second read (triggers offsetInBuffer logic)
        Assert.assertEquals(4, zais.read(buffer, 0, 4));
        Assert.assertEquals("efgh", new String(buffer, 0, 4));

        // Third read (partial remaining)
        Assert.assertEquals(2, zais.read(buffer, 0, 4));
        Assert.assertEquals("ij", new String(buffer, 0, 2));

        // End of entry
        Assert.assertEquals(-1, zais.read(buffer, 0, 4));
    }

    // Helper to create normal DEFLATED zip
    private byte[] createZipData(String name, String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(name);
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    // Helper to create STORED zip
    private byte[] createStoredZipData(String name, String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(name);
            entry.setMethod(java.util.zip.ZipEntry.STORED);
            entry.setSize(content.length());
            entry.setCompressedSize(content.length());
            entry.setCrc(calculateCrc(content.getBytes()));
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
        }
        return baos.toByteArray();
    }

    private long calculateCrc(byte[] data) {
        java.util.zip.CRC32 crc = new java.util.zip.CRC32();
        crc.update(data);
        return crc.getValue();
    }
}
